CREATE TABLE club_details(organization_id BIGINT PRIMARY KEY REFERENCES organizations(id),meeting_cycle VARCHAR(2000),entry_fee INTEGER NOT NULL DEFAULT 0 CHECK(entry_fee>=0),photo_url VARCHAR(2000),recruitment_mode VARCHAR(20) NOT NULL DEFAULT 'ALWAYS' CHECK(recruitment_mode IN ('ALWAYS','PERIOD','CLOSED')),opens_at TIMESTAMPTZ,closes_at TIMESTAMPTZ);
CREATE TABLE club_subscriptions(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES organizations(id),user_id BIGINT NOT NULL REFERENCES app_users(id),notified BOOLEAN NOT NULL DEFAULT false,UNIQUE(organization_id,user_id));
